(window.LADDER_CARDS=window.LADDER_CARDS||{})["21·nav2"]=[{"q": "Speed of a circular orbit of radius r about a body with gravitational parameter GM?", "a": "√(GM/r)", "w": ["√(2GM/r)", "GM/r²", "√(GMr)"], "why": "Gravity supplies v²/r."}, {"q": "An orbit four times as far out. How does the circular speed compare?", "a": "half", "w": ["a quarter", "twice", "the same"], "why": "v ∝ 1/√r."}, {"q": "The ellipse touching a lower circular orbit at one end and a higher one at the other. What is it called?", "a": "a Hohmann transfer orbit", "w": ["a gravity assist", "a geostationary orbit", "a parabolic escape"], "why": "The cheapest two-burn transfer between circles."}, {"q": "Kepler’s equal areas at the two ends of an ellipse gives what relation?", "a": "r₁v₁ = r₂v₂", "w": ["v₁/r₁ = v₂/r₂", "r₁²v₁ = r₂²v₂", "v₁ = v₂"], "why": "Conservation of angular momentum."}, {"q": "v² = GM(2/r − 1/a). What is the equation called?", "a": "the vis-viva equation", "w": ["Kepler’s third law", "the rocket equation", "Newton’s second law"], "why": "Energy conserved along an orbit."}, {"q": "Kepler’s third law in years and astronomical units. What is the period of an orbit with semi-major axis 4 AU?", "a": "8 years", "w": ["4 years", "16 years", "2 years"], "why": "T = a^(3/2)."}, {"q": "How long does a Hohmann transfer take?", "a": "half the period of the transfer ellipse", "w": ["the full period of the ellipse", "the period of the target’s orbit", "the time light takes"], "why": "From one end of the ellipse to the other."}, {"q": "At the outer end of a Hohmann transfer to a higher orbit, how does the craft’s speed compare with the circular speed there?", "a": "slower, so a forward burn is needed", "w": ["faster, so a backward burn is needed", "the same", "zero"], "why": "Coasting outward, the craft slowed."}, {"q": "The time for Earth to gain one full lap on another planet. What is it called?", "a": "the synodic period", "w": ["the sidereal period", "the transfer time", "the launch window"], "why": "For Mars, about 26 months."}, {"q": "A craft behind a station on the same circular orbit. To catch up, which way does it burn first?", "a": "backward, to drop to a shorter-period orbit", "w": ["forward, to speed up", "sideways", "no burn: it catches up by itself"], "why": "Orbital rendezvous."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{});(window.LADDER_CARDS["21·nav2"]=window.LADDER_CARDS["21·nav2"]||[]).push(
 {"u": "21·nav2.1.1", "q": "How fast does a body go round a circle about the sun at distance r, and why is a farther planet slower?", "a": "the sun’s pull GM/r² per kilogram must be the v²/r the circle needs, so v = √(GM/r); a farther circle has a weaker pull and so a slower speed, as 1/√r", "w": ["v = GM/r²; farther planets are faster", "v = √(GMr); farther planets are faster", "every planet has the same speed"], "why": "Newton’s law and the circle’s pull (21·phys)."},
 {"u": "21·nav2.2.1", "q": "What two rules hold at the ends of the transfer ellipse, and what speed do they give at the near end?", "a": "equal areas, r₁v₁ = r₂v₂, and the same energy, ½v² − GM/r, at both ends; together they give v₁² = (GM/r₁) · 2r₂/(r₁ + r₂), faster than the near circle by √(2r₂/(r₁ + r₂))", "w": ["equal speeds at both ends; v₁ = √(GM/r₁)", "equal distances; v₁ = √(GM/r₂)", "equal times; v₁ = 2√(GM/r₁)"], "why": "The ends technique."},
 {"u": "21·nav2.3.1", "q": "What are the two pushes of a transfer outward, and why is the craft slower than the outer planet when it arrives?", "a": "a forward push from the inner circle’s speed up to the ellipse’s near-end speed, and a forward push at the far end from the ellipse’s speed up to the outer circle’s; coasting outward the sun slowed it, so at the far end it is below the circle speed there", "w": ["a forward push and a backward push; it arrives faster", "one push only; it arrives at the planet’s speed", "two backward pushes; it arrives faster"], "why": "Both pushes are forward."},
 {"u": "21·nav2.4.1", "q": "How long does the transfer take, and how far ahead must the target be at departure?", "a": "half the transfer ellipse’s period, by Kepler’s third law, a^(3/2) years; the target must lead by half a turn less the angle it moves during the trip", "w": ["the target’s full period; it must be directly overhead", "one year; it must lead by 90°", "the inner planet’s period; it must trail by half a turn"], "why": "The window technique."},
 {"u": "21·nav2.5.1", "q": "Why does a craft that wants to gain on a station ahead on the same orbit push backward rather than forward?", "a": "a forward push raises it onto a larger orbit with a longer period, so it falls further behind; a backward push drops it onto a smaller orbit with a shorter period, so after one lap it has gained, and a forward push there rejoins the circle", "w": ["a backward push makes it faster at once", "forward and backward are the same in orbit", "a backward push leaves orbit entirely"], "why": "Slow down to catch up."},
 {"u": "21·nav2.6.1", "q": "Which move above turns the equal-areas rule upside down, and how does r₁v₁ = r₂v₂ set it right?", "a": "the move that writes v₂ = v₁r₂/r₁: equal areas give r₁v₁ = r₂v₂, so v₂ = v₁r₁/r₂, slower at the farther end", "w": ["the move that aims at the planet: equal areas give v₂ = v₁", "the move that stops with a backward push: equal areas give r₁ = r₂", "the move that leaves with the planet overhead: equal areas give v₂ = 2v₁"], "why": "Farther means slower."});
/*end gapcards 21·nav2*/
