(window.LADDER_CARDS=window.LADDER_CARDS||{})["24·nav"]=[{"q": "Finding position by integrating measured accelerations and turn rates, with no outside reference. What is it called?", "a": "inertial navigation", "w": ["dead reckoning by log", "celestial navigation", "radio direction finding"], "why": "Accelerometers and gyroscopes."}, {"q": "An accelerometer bias of 0.002 m/s². What position error does it build in 1000 s?", "a": "1000 m", "w": ["2 m", "2000 m", "1 m"], "why": "½bt² = ½ · 0.002 · 10⁶."}, {"q": "With a steady acceleration bias, the time is doubled. What happens to the position error?", "a": "it is multiplied by 4", "w": ["it doubles", "it stays the same", "it is multiplied by 8"], "why": "Error ∝ t²."}, {"q": "An accelerometer tilted by a small angle θ from level. What false horizontal acceleration does it read?", "a": "g sin θ", "w": ["g cos θ", "g/θ", "zero"], "why": "It cannot tell gravity from a push."}, {"q": "A platform kept level by its own computed position oscillates in error with what period?", "a": "about 84 minutes", "w": ["about 24 hours", "about 12 minutes", "about 1 second"], "why": "The Schuler period."}, {"q": "The Schuler period in terms of the earth’s radius R and gravity g?", "a": "2π√(R/g)", "w": ["2π√(g/R)", "√(R/g)", "2πR/g"], "why": "A pendulum as long as the earth’s radius."}, {"q": "Designing an inertial system so its level errors swing rather than grow. What is it called?", "a": "Schuler tuning", "w": ["Kalman tuning", "gyro caging", "dithering"], "why": "Max Schuler, 1923."}, {"q": "At 200 m/s with a steady heading error of 0.001 rad, how far off course is the craft after 1000 s?", "a": "200 m", "w": ["0.2 m", "20 m", "2000 m"], "why": "vεt; a drifting heading makes it grow as t²."}, {"q": "A standard way to blend inertial navigation with outside position fixes?", "a": "a Kalman filter", "w": ["a Fourier transform", "a low-pass resistor", "a Monte Carlo search"], "why": "Sensor fusion."}, {"q": "Who showed that a device kept level over the round earth swings with a period near 84 minutes, and when?", "a": "Max Schuler, 1923", "w": ["Charles Stark Draper, 1953", "Elmer Sperry, 1911", "Léon Foucault, 1851"], "why": "Draper’s lab later built submarine and Apollo systems."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{});(window.LADDER_CARDS["24·nav"]=window.LADDER_CARDS["24·nav"]||[]).push(
 {"u": "24·nav.1.1", "q": "How does a craft find its place from the pushes it feels, and how often is each error in the acceleration added up?", "a": "speed is the start speed plus the area under the acceleration, and place is the start place plus the area under the speed, so place comes from acceleration integrated twice; every error in the reading is added up twice", "w": ["place is acceleration times time; each error is added once", "place is read directly from the spring; errors are not added", "speed is the area under place; each error cancels"], "why": "Two initial value problems."},
 {"u": "24·nav.2.1", "q": "How does a steady error in the acceleration reading grow the error in place, and what does that mean over time?", "a": "the error obeys e″ = b with e and e′ starting at 0, so e = ½bt²; it grows as the square of the time, so twice the time gives four times the error", "w": ["e = bt; twice the time gives twice the error", "e = b; the error stays fixed", "e = ½bt; it grows slowly then stops"], "why": "The twice-added technique."},
 {"u": "24·nav.3.1", "q": "Why does a small tilt of the sensor cost far more than a small spring error, and why is level itself a moving target?", "a": "a spring cannot tell gravity from a push, so a tilt θ puts about gθ of gravity into a sideways reading, and g is large; on a round earth, down turns as the craft moves, so the sensor must be re-levelled continually", "w": ["tilt does not affect the reading; level is fixed in space", "a tilt adds θ, the same size as the spring error; level never changes", "a tilt only changes the vertical reading; level is set once"], "why": "Gravity looks like a push."},
 {"u": "24·nav.4.1", "q": "How does levelling the sensor by its own computed place turn a growing error into a swing, and what is the swing’s period?", "a": "an error y in place tilts the sensor by y/R, which reads as a push of gy/R back toward the truth, so y″ = −(g/R)y, a steady swing with period 2π√(R/g), about 84 minutes", "w": ["the error is cancelled at once; there is no period", "the error grows as t³; the period is a day", "the error swings with period √(g/R), about one second"], "why": "The levelling technique."},
 {"u": "24·nav.5.1", "q": "Why does a drift in heading still grow, and why is inertial navigation always mixed with outside fixes?", "a": "gravity does not pull a heading error back, so a steady drift makes the heading, then the sideways speed, then the place error grow, as ½vωt²; the system is excellent over minutes but drifts over hours, so outside fixes reset it", "w": ["heading drift is pulled back like level error; outside fixes are only for comfort", "heading cannot drift; fixes are needed for depth only", "heading drift shrinks over time; fixes are never needed"], "why": "Sensor fusion."},
 {"u": "24·nav.6.1", "q": "Which move above adds the error in acceleration up only once, and how fast does it really grow?", "a": "the move that gives an error in place of 0.001t: the error is added up twice, so it grows as ½bt²", "w": ["the move that levels by a fixed direction: it grows as t³", "the move that thinks the spring tells gravity from a push: it does not grow", "the move that finds speed after place: it grows as √t"], "why": "Twice added."});
/*end gapcards 24·nav*/
