(window.LADDER_CARDS=window.LADDER_CARDS||{})["28·nav"]=[{"q": "A frame centred at the earth’s centre, turning with the earth, z toward the north pole. What is it called?", "a": "earth-centred, earth-fixed (ECEF)", "w": ["east-north-up (ENU)", "the body frame", "the inertial star frame"], "why": "x toward latitude 0, longitude 0."}, {"q": "A local frame at a place on the earth with axes east, north and up. What is it called?", "a": "east-north-up (ENU)", "w": ["ECEF", "north-east-down body frame", "the ecliptic frame"], "why": "A local tangent plane."}, {"q": "On a ball of radius R, where is latitude 0, longitude 90° east, height 0, in the earth frame?", "a": "(0, R, 0)", "w": ["(R, 0, 0)", "(0, 0, R)", "(R, R, 0)"], "why": "x = R cos φ cos λ, y = R cos φ sin λ."}, {"q": "The local ‘up’ arrow at the north pole, in earth-frame parts?", "a": "(0, 0, 1)", "w": ["(1, 0, 0)", "(0, 1, 0)", "(0, 0, −1)"], "why": "up = (cos φ cos λ, cos φ sin λ, sin φ)."}, {"q": "For a rotation matrix T, what is T⁻¹?", "a": "Tᵀ", "w": ["−T", "T itself", "1/det T times T"], "why": "Orthogonal: TᵀT = I."}, {"q": "Two rotations of space, R₁ and R₂. Is R₁R₂ always equal to R₂R₁?", "a": "no: rotations in three dimensions need not commute", "w": ["yes, always", "only for 90° turns", "only for turns about one point"], "why": "So Euler angles need an agreed order."}, {"q": "With pitch at 90°, the first and last turns are about the same axis and one angle is lost. What is this called?", "a": "gimbal lock", "w": ["dead band", "aliasing", "drift"], "why": "Apollo 11’s platform had to avoid it."}, {"q": "Which description of attitude avoids gimbal lock?", "a": "unit quaternions", "w": ["Euler angles in another order", "degrees instead of radians", "two angles only"], "why": "Four numbers, no lost angle."}, {"q": "(ABC)⁻¹ for invertible matrices A, B, C?", "a": "C⁻¹B⁻¹A⁻¹", "w": ["A⁻¹B⁻¹C⁻¹", "A⁻¹C⁻¹B⁻¹", "(CBA)"], "why": "Undo in reverse order."}, {"q": "Euler, 1776: every rotation of space about a fixed point is what?", "a": "a rotation about a single axis through that point", "w": ["a sum of two reflections in parallel planes", "a translation", "a rotation about three axes at once"], "why": "Euler’s rotation theorem."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{});(window.LADDER_CARDS["28·nav"]=window.LADDER_CARDS["28·nav"]||[]).push(
 {"u": "28·nav.1.1", "q": "What frames does a craft navigate with, and how are an arrow’s parts in a frame found?", "a": "an earth frame from the earth’s centre, a local east-north-up frame at the craft’s place, and a craft frame of nose, right wing and down; an arrow’s parts in a frame are its dot products with that frame’s three unit arrows", "w": ["one frame serves for all; parts are the arrow’s length", "the parts are the same in every frame", "parts are found by adding the frame’s arrows"], "why": "The read-off technique."},
 {"u": "28·nav.2.1", "q": "How is a place written in the earth frame from its latitude, longitude and height, and where do east, north and up come from?", "a": "x = (R + h)cos φ cos λ, y = (R + h)cos φ sin λ, z = (R + h)sin φ; up is that direction scaled to length 1, and east and north are the slopes of the place in λ and φ scaled to length 1", "w": ["x = λ, y = φ, z = h; the directions are fixed for all places", "x = R sin φ, y = R cos λ, z = h; up is always (0, 0, 1)", "place cannot be written in the earth frame"], "why": "Cos and sin as parts."},
 {"u": "28·nav.3.1", "q": "How does the grid of a frame’s arrows change parts into that frame, and why is its undo its side-turn?", "a": "with the frame’s arrows as its rows, the grid times earth parts gives the dots with each arrow, the frame’s parts; the rows have length 1 and are at right angles, so TᵀT = I and T⁻¹ = Tᵀ", "w": ["the grid’s columns are the arrows; its undo needs elimination", "the grid adds the arrows; its undo is −T", "the grid has no undo"], "why": "The frame technique."},
 {"u": "28·nav.4.1", "q": "Why must heading, pitch and roll be applied in an agreed order, and what happens when the nose points straight up?", "a": "turns of space do not commute, so different orders give different attitudes; with the nose straight up the first and last turns are about the same line, and the three angles are no longer fixed by the attitude", "w": ["the order does not matter; nothing happens", "the order matters only for small angles; the angles become infinite", "the order is fixed by gravity; the craft stops turning"], "why": "Gimbal lock."},
 {"u": "28·nav.5.1", "q": "How does a reading pass through a chain of frames, and why is the way back the side-turns in reverse order?", "a": "multiply by each frame’s turn grid in turn, adding each frame’s point for positions; a product is undone by undoing its last step first, so the way back is the side-turns in reverse order", "w": ["add the grids; the way back is subtracting them in any order", "multiply in any order; the way back is the same grids again", "only the last frame matters; there is no way back"], "why": "The chain technique."},
 {"u": "28·nav.6.1", "q": "Which move above undoes the chain of turns in the same order, and what order does undressing in reverse give?", "a": "the move that writes (ABC)⁻¹ = A⁻¹B⁻¹C⁻¹: the undo is C⁻¹B⁻¹A⁻¹, the last turn undone first", "w": ["the move that adds the points to arrows: ABC", "the move that inverts by elimination: CBA", "the move that swaps roll and heading: A⁻¹C⁻¹B⁻¹"], "why": "Undress in reverse."});
/*end gapcards 28·nav*/
