(window.LADDER_CARDS=window.LADDER_CARDS||{})["31·nav"]=[{"q": "Two independent estimates with spreads 3 and 4. What weight goes on the first in the best blend?", "a": "0.64", "w": ["0.36", "0.75", "0.5"], "why": "Inverse-variance weighting: 16/(9 + 16)."}, {"q": "Same two estimates, spreads 3 and 4. What is the blend’s spread squared?", "a": "5.76", "w": ["12.5", "9", "25"], "why": "1/σ² = 1/9 + 1/16."}, {"q": "Guess spread² P = 36, measurement spread² R = 12. What is the Kalman gain?", "a": "0.75", "w": ["0.25", "3", "0.33"], "why": "K = P/(P + R)."}, {"q": "Guess 50, measurement 58, gain 0.25. What is the updated estimate?", "a": "52", "w": ["56", "54", "58"], "why": "50 + 0.25 · 8."}, {"q": "P = 40 before a fix, gain 0.25. What is P after the update?", "a": "30", "w": ["10", "40", "50"], "why": "(1 − K)P."}, {"q": "Between fixes, with process noise Q, how does P change in the predict step?", "a": "P → P + Q", "w": ["P → P − Q", "P → PQ", "P → P/(P + Q)"], "why": "Spreads squared add."}, {"q": "The loop of predicting and blending by a gain set from the spreads. What is it called, and who published it?", "a": "the Kalman filter; Rudolf Kálmán, 1960", "w": ["the Wiener filter; Norbert Wiener, 1949", "the particle filter; Gordon, 1993", "the Kalman filter; Stanley Schmidt, 1970"], "why": "Schmidt adapted it for Apollo."}, {"q": "With steady Q and R, the settled spread solves what kind of equation?", "a": "a Riccati equation", "w": ["a Bessel equation", "a wave equation", "a Bellman equation"], "why": "In one dimension, a quadratic."}, {"q": "A Kalman filter for motion or measurements that are not straight lines, using the slope at each step. What is it called?", "a": "the extended Kalman filter", "w": ["the steady-state filter", "the complementary filter", "the moving-average filter"], "why": "The unscented filter is another version."}, {"q": "Q = 9 and R = 100. Where does the predicted spread² M settle?", "a": "about 34.8", "w": ["about 9", "about 100", "about 25.8"], "why": "M² − QM − QR = 0, positive root."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{});(window.LADDER_CARDS["31·nav"]=window.LADDER_CARDS["31·nav"]||[]).push(
 {"u": "31·nav.1.1", "q": "How is the best weight for blending two independent estimates found, and why is the blend better than either?", "a": "the blend’s spread squared is w²σ_a² + (1 − w)²σ_b², and setting its slope to zero gives weights inverse to the spreads squared; the result has 1/σ² = 1/σ_a² + 1/σ_b², smaller than either", "w": ["weight them equally; the blend is as good as the average", "keep the better one; blending can only add error", "weight by the spreads themselves; the blend has the larger spread"], "why": "The blend technique."},
 {"u": "31·nav.2.1", "q": "How is the blend written as a gain times the miss, and what happens to the guess’s spread squared?", "a": "the blend is the guess plus K times the miss, with K = P/(P + R); the guess’s spread squared becomes (1 − K)P, smaller", "w": ["the blend is the measurement times K; P grows to P + R", "K = R/(P + R); P is unchanged", "the miss is ignored; P halves"], "why": "The gain technique."},
 {"u": "31·nav.3.1", "q": "What happens to the estimate and its spread between fixes, and why does the next gain rise?", "a": "the estimate moves with the known motion and its spread squared grows by the motion’s error Q; a less sure guess gives a larger P/(P + R), so it listens more to the next fix", "w": ["the estimate stays put and P shrinks; the gain falls", "the estimate jumps to the last fix; the gain stays fixed", "P becomes zero; the gain becomes 1"], "why": "The predict step."},
 {"u": "31·nav.4.1", "q": "Where do the gain and spread settle, and how is that point found?", "a": "they settle where predicting adds as much as blending removes: with M = P + Q and P = MR/(M + R), clearing fractions gives M² − QM − QR = 0, whose positive root fixes M, then K = M/(M + R)", "w": ["they never settle; the gain grows forever", "they settle at K = 1 and P = 0", "they settle at K = Q/R, found by trial"], "why": "The settling technique."},
 {"u": "31·nav.5.1", "q": "How do the two steps look with many numbers, and why can a fix of one quantity sharpen another?", "a": "predict x → Fx, P → FPFᵀ + Q; gain K = PHᵀ(HPHᵀ + R)⁻¹; update x → x + K(z − Hx), P → (I − KH)P; the grid P links the quantities, so a fix of speed moves the place estimate too", "w": ["each number gets its own one-number filter; quantities never interact", "the grids are added, not multiplied; a speed fix only changes speed", "the many-number form needs no gain; fixes measure everything"], "why": "The grid form."},
 {"u": "31·nav.6.1", "q": "Which move above puts R on top of the gain, and what would that make a sure guess do?", "a": "the move that writes K = R/(P + R): with a sure guess, P small, it would give K near 1, throwing the good guess away for the measurement", "w": ["the move that averages 100 and 106: K = ½", "the move that blends before moving: K = 0", "the move that only shrinks: K = P"], "why": "A surer guess should listen less."});
